<template>
  <div class="training-page">
    <div class="page-heading"><div><div class="eyebrow">GYMMIND TRAINING</div><h2>{{ profile.title }}</h2><p>{{ profile.description }}</p></div><el-button v-if="isMember" type="primary" @click="showRecord=true">开始训练</el-button></div>
    <div class="toolbar simple-card"><el-radio-group v-model="range" @change="load"><el-radio-button value="7">本周</el-radio-button><el-radio-button value="30">近30天</el-radio-button><el-radio-button value="90">近90天</el-radio-button></el-radio-group><el-button @click="load">刷新概览</el-button></div>
    <div class="stats-grid"><div v-for="s in stats" :key="s.label" class="stat-card"><span>{{s.label}}</span><strong>{{s.value}}</strong></div></div>
    <div class="simple-card panel"><div class="heading"><h3>健身房训练计划库</h3><el-select v-model="category" clearable placeholder="全部分类" style="width:150px"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select></div><div class="plan-grid"><div v-for="p in filteredTemplates" :key="p.id" class="plan-card" @click="viewPlan(p.id)"><small>{{p.category}}</small><h4>{{p.name}}</h4><p>{{p.description}}</p><el-button type="primary" link @click.stop="viewPlan(p.id)">查看计划详情</el-button><el-button v-if="isMember" type="primary" link @click.stop="choosePlan(p.id)">加入我的计划</el-button><el-button v-else-if="canManage" type="success" link @click.stop="publishPlan(p)">发布</el-button></div></div><el-empty v-if="!filteredTemplates.length" description="暂无已发布训练计划"/></div>
    <div v-if="isMember" class="simple-card panel"><div class="heading"><h3>我的训练日历</h3><el-date-picker v-model="calendarDate" type="date" value-format="YYYY-MM-DD" @change="loadCalendar"/></div><el-table :data="calendarRows" stripe><el-table-column prop="scheduledDate" label="日期"/><el-table-column prop="planName" label="训练计划"/><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="startScheduled(s.row)">开始训练</el-button></template></el-table-column></el-table><el-empty v-if="!calendarRows.length" description="暂无排期"/></div>
    <div class="simple-card panel"><div class="heading"><h3>{{isMember?'我的训练记录':'训练概览'}}</h3></div><el-table :data="data.records" stripe><el-table-column prop="workoutDate" label="日期"/><el-table-column prop="duration" label="时长（分钟）"/><el-table-column prop="calories" label="消耗热量"/><el-table-column prop="notes" label="备注"/></el-table><el-empty v-if="!data.records.length" description="暂无训练记录"/></div>
    <el-dialog v-model="showRecord" title="记录一次训练" width="520px"><el-form label-position="top"><el-form-item label="训练日期"><el-date-picker v-model="form.workoutDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="训练时长（分钟）"><el-input-number v-model="form.duration" :min="1"/></el-form-item><el-form-item label="动作 ID（历史记录兼容）"><el-input-number v-model="form.exerciseId" :min="1"/></el-form-item><el-form-item label="备注"><el-input v-model="form.notes" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="showRecord=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveRecord">保存</el-button></template></el-dialog>
    <el-dialog v-model="showPlan" :title="selectedPlan?.name || '训练计划详情'" width="700px"><div v-if="selectedPlan"><p class="plan-description">{{selectedPlan.description}}</p><div v-for="phase in phases" :key="phase" class="phase-block"><h4>{{phaseLabels[phase]}}</h4><el-table :data="selectedPlan.items?.filter(i=>i.phase===phase) || []" stripe><el-table-column prop="exerciseName" label="动作" min-width="150"/><el-table-column label="训练安排"><template #default="s">{{s.row.reps}} 次 × {{s.row.sets}} 组</template></el-table-column><el-table-column label="休息"><template #default="s">{{s.row.restSeconds}} 秒</template></el-table-column><el-table-column prop="notes" label="备注" min-width="240"/></el-table></div></div><template #footer><el-button v-if="isMember && selectedPlan" type="primary" @click="choosePlan(selectedPlan.id);showPlan=false">加入我的计划</el-button><el-button @click="showPlan=false">关闭</el-button></template></el-dialog>
  </div>
    <el-button v-if="canManage" type="primary" @click="showCreate=true">新建训练计划</el-button>
    <el-dialog v-model="showCreate" title="新建训练计划" width="720px"><el-form label-position="top"><el-form-item label="计划名称"><el-input v-model="createForm.name" placeholder="例如：胸部力量入门"/></el-form-item><el-form-item label="分类"><el-select v-model="createForm.category" placeholder="选择分类"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select></el-form-item><el-form-item label="训练目标"><el-input v-model="createForm.goal"/></el-form-item><el-form-item label="计划说明"><el-input v-model="createForm.description" type="textarea"/></el-form-item><el-divider>动作安排</el-divider><div v-for="(item,index) in createForm.items" :key="index" class="create-item"><el-select v-model="item.phase" placeholder="阶段"><el-option label="热身" value="WARMUP"/><el-option label="正式" value="MAIN"/><el-option label="拉伸" value="STRETCH"/></el-select><el-input v-model="item.exerciseName" placeholder="动作名称，例如：哑铃卧推"/><el-input-number v-model="item.reps" :min="1" placeholder="次数"/><span>次 ×</span><el-input-number v-model="item.sets" :min="1" placeholder="组数"/><el-input v-model="item.notes" placeholder="动作说明"/></div><el-button link type="primary" @click="addCreateItem">+ 添加动作</el-button></el-form><template #footer><el-button @click="showCreate=false">取消</el-button><el-button type="primary" :loading="creating" @click="createPlan">保存并发布</el-button></template></el-dialog>
</template>
<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'; import {ElMessage} from 'element-plus'; import {useAuthStore} from '@/stores/auth'; import {trainingApi,type TrainingOverview,type TrainingTemplate} from '@/api/training'; import {workoutRecordsApi} from '@/api/workouts';
const auth=useAuthStore(); const loading=ref(false); const saving=ref(false); const creating=ref(false); const range=ref('30'); const showRecord=ref(false); const showPlan=ref(false); const showCreate=ref(false); const selectedPlan=ref<TrainingTemplate>(); const category=ref(''); const templates=ref<TrainingTemplate[]>([]); const calendarDate=ref(new Date().toISOString().slice(0,10)); const calendarRows=ref<any[]>([]);
const data=ref<TrainingOverview>({role:'',since:'',until:'',summary:{workoutCount:0,activeMembers:0,totalMinutes:0,averageMinutes:0,streakDays:0},records:[],members:[]}); const form=reactive({workoutDate:calendarDate.value,duration:45,exerciseId:1,notes:'完成今日训练'});
const isMember=computed(()=>auth.roles.includes('MEMBER')&&!auth.isPlatformAdmin); const canManage=computed(()=>auth.roles.includes('COACH')||auth.roles.includes('GYM_ADMIN')); const profile=computed(()=>isMember.value?{title:'我的训练',description:'选择计划，安排到日历并记录每次训练。'}:{title:'训练计划管理',description:'发布门店共享计划，查看会员训练进度。'}); const stats=computed(()=>[{label:'训练次数',value:data.value.summary.workoutCount},{label:'训练人数',value:data.value.summary.activeMembers},{label:'总时长',value:data.value.summary.totalMinutes+' 分钟'},{label:'平均每次',value:Math.round(data.value.summary.averageMinutes)+' 分钟'},{label:'连续训练',value:data.value.summary.streakDays+' 天'}]); const categories=['肩','背','胸','手臂','臀腿','推日','拉日']; const filteredTemplates=computed(()=>templates.value.filter(p=>!category.value||p.category===category.value));
const phases=['WARMUP','MAIN','STRETCH']; const phaseLabels:Record<string,string>={WARMUP:'热身动作',MAIN:'正式动作',STRETCH:'拉伸动作'};
const createForm=reactive({name:'',category:'',goal:'',description:'',items:[{exerciseName:'',phase:'WARMUP',sortOrder:1,sets:2,reps:15,restSeconds:30,weight:0,notes:''}]});
async function load(){loading.value=true;try{const e=new Date(),s=new Date();s.setDate(e.getDate()-Number(range.value)+1);data.value=(await trainingApi.overview(s.toISOString().slice(0,10),e.toISOString().slice(0,10))).data;templates.value=(await trainingApi.templates()).data;if(isMember.value)await loadCalendar()}catch(e:any){ElMessage.error(e?.response?.data?.message||'训练数据加载失败')}finally{loading.value=false}}
async function choosePlan(id:number){try{const p=(await trainingApi.select(id)).data;await trainingApi.schedule(p.id,calendarDate.value);ElMessage.success('已加入今天的训练日历');await loadCalendar()}catch(e:any){ElMessage.error(e?.response?.data?.message||'加入失败')}}
async function viewPlan(id:number){try{selectedPlan.value=(await trainingApi.template(id)).data;showPlan.value=true}catch(e:any){ElMessage.error(e?.response?.data?.message||'计划详情加载失败')}}
function addCreateItem(){createForm.items.push({exerciseName:'',phase:'MAIN',sortOrder:createForm.items.length+1,sets:3,reps:10,restSeconds:90,weight:0,notes:''})} async function createPlan(){if(!createForm.name||!createForm.category||!createForm.goal||createForm.items.some(item=>!item.exerciseName.trim())){ElMessage.warning('请填写计划基本信息和每个动作名称');return}creating.value=true;try{const created=(await trainingApi.createTemplate(createForm)).data;await trainingApi.publish(created.id);ElMessage.success('训练计划已创建并发布');showCreate.value=false;await load()}catch(e:any){ElMessage.error(e?.response?.data?.message||'创建失败')}finally{creating.value=false}}
async function loadCalendar(){const from=new Date(calendarDate.value);from.setDate(1);const to=new Date(from);to.setMonth(to.getMonth()+1);const rows=(await trainingApi.calendar(from.toISOString().slice(0,10),to.toISOString().slice(0,10))).data;calendarRows.value=rows.map((x:any)=>({...x,planName:'我的训练计划 #'+x.memberPlanId}))}
async function publishPlan(p:TrainingTemplate){try{await trainingApi.publish(p.id);ElMessage.success('计划已发布');await load()}catch(e:any){ElMessage.error(e?.response?.data?.message||'发布失败')}} function startScheduled(row:any){form.workoutDate=row.scheduledDate;showRecord.value=true}
async function saveRecord(){saving.value=true;try{await workoutRecordsApi.create({workoutDate:form.workoutDate,duration:form.duration,calories:200,notes:form.notes,sets:[{exerciseId:form.exerciseId,setNumber:1,weight:0,reps:10,duration:0,completed:true}]});showRecord.value=false;ElMessage.success('训练记录已保存');await load()}catch(e:any){ElMessage.error(e?.response?.data?.message||'保存失败')}finally{saving.value=false}}
onMounted(load)
</script>
<style scoped>.training-page{max-width:1100px;margin:auto}.page-heading,.toolbar,.heading{display:flex;align-items:center;justify-content:space-between;gap:14px}.toolbar{margin:18px 0;padding:14px}.stats-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:16px}.stat-card,.panel{padding:18px}.stat-card{border:1px solid var(--border);border-radius:8px;background:#fff}.stat-card span{display:block;color:var(--text-muted);font-size:12px}.stat-card strong{display:block;color:var(--primary);font-size:24px;margin-top:8px}.panel{margin-bottom:16px}.plan-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.plan-card{border:1px solid var(--border);padding:14px;border-radius:8px}.plan-card h4{margin:8px 0}.plan-card p{color:var(--text-muted);min-height:40px}@media(max-width:800px){.stats-grid{grid-template-columns:repeat(2,1fr)}.plan-grid{grid-template-columns:1fr}}</style>
